create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
do $$ declare t text; begin foreach t in array array['socios','transportadoras','recebimentos_transportadoras','motoboys','pagamentos_motoboys','custos','vales_extravios','fechamentos','repasses_socios','configuracoes'] loop execute format('drop trigger if exists trg_updated_at on public.%I',t); execute format('create trigger trg_updated_at before update on public.%I for each row execute function public.set_updated_at()',t); end loop; end $$;
create or replace function public.validar_percentuais_socios() returns trigger language plpgsql as $$ declare total numeric; begin select coalesce(sum(percentual_participacao),0) into total from public.socios where ativo and id<>new.id; if round(total+new.percentual_participacao,2)<>100 then raise exception 'A soma dos percentuais ativos deve ser 100%%'; end if; return new; end $$;
create or replace function public.resumo_periodo(p_tipo text,p_numero smallint,p_mes smallint,p_ano smallint) returns table(total_recebido numeric,total_motoboys numeric,total_custos numeric,lucro_liquido numeric,margem_liquida numeric) language sql stable security invoker as $$ with r as(select coalesce(sum(valor),0) v from public.recebimentos_transportadoras where tipo_periodo=p_tipo and numero_periodo=p_numero and mes=p_mes and ano=p_ano and status='recebido'),m as(select coalesce(sum(valor_liquido),0) v from public.pagamentos_motoboys where tipo_periodo=p_tipo and numero_periodo=p_numero and mes=p_mes and ano=p_ano and status='pago'),c as(select coalesce(sum(valor),0) v from public.custos where mes=p_mes and ano=p_ano and status='pago') select r.v,m.v,c.v,round(r.v-m.v-c.v,2),case when r.v=0 then 0 else round(((r.v-m.v-c.v)/r.v)*100,2) end from r,m,c $$;

